    // unchanged substring scan below (byte-identical jiraSource behavior).
    if (/^pr-(\d+)$/.test(String(ticketKey || ''))) {
        return ghHelpers.findPRForTicket(scm, ticketKey);
    }
    try {
        const openPRs = scm.listPrs('open');

